<?php
if(!defined('ABSPATH'))exit;
class SMF_Profitability{
 public static function init(){add_action('admin_init',array(__CLASS__,'settings'));add_action('admin_menu',array(__CLASS__,'menu'),31);}
 public static function settings(){foreach(array('smf_cogs_percent'=>0,'smf_payment_fee_percent'=>0,'smf_courier_delivery_cost'=>0,'smf_courier_return_cost'=>0) as $k=>$v)add_option($k,$v);register_setting('smf_settings','smf_cogs_percent',array('sanitize_callback'=>array(__CLASS__,'pct')));register_setting('smf_settings','smf_payment_fee_percent',array('sanitize_callback'=>array(__CLASS__,'pct')));register_setting('smf_settings','smf_courier_delivery_cost',array('sanitize_callback'=>array(__CLASS__,'money')));register_setting('smf_settings','smf_courier_return_cost',array('sanitize_callback'=>array(__CLASS__,'money')));}
 public static function pct($v){return max(0,min(100,(float)$v));}
 public static function money($v){return max(0,(float)$v);}
 public static function menu(){add_submenu_page('sync-meta-flow','Profitability Intelligence','Profitability Intelligence','manage_woocommerce','smf-profitability',array(__CLASS__,'render'));}
 private static function touch($m,$prefix){$x=array();foreach(array('campaign_id','campaign_name','adset_id','ad_id','utm_campaign') as $k){$key=$prefix?$prefix.'_'.$k:$k;if(isset($m[$key])&&$m[$key]!=='')$x[$k]=sanitize_text_field((string)$m[$key]);}return $x;}
 private static function campaign($t){if(!empty($t['campaign_id']))return $t['campaign_id'];if(!empty($t['campaign_name']))return $t['campaign_name'];if(!empty($t['utm_campaign']))return $t['utm_campaign'];return 'Direct / Unattributed';}
 public static function report($days=30,$currency='BDT',$model='last_touch'){
  global $wpdb;$days=in_array((int)$days,array(7,30,90),true)?(int)$days:30;$until=current_time('Y-m-d');$since=wp_date('Y-m-d',strtotime('-'.($days-1).' days',current_time('timestamp')));$e=$wpdb->prefix.'smf_order_events';$s=$wpdb->prefix.'smf_campaign_spend';
  $ids=$wpdb->get_col($wpdb->prepare("SELECT DISTINCT order_id FROM $e WHERE event_type='purchase' AND created_at BETWEEN %s AND %s",$since.' 00:00:00',$until.' 23:59:59'));$orders=array();if($ids){$in=implode(',',array_map('absint',$ids));$events=$wpdb->get_results("SELECT order_id,event_type,old_status,new_status,metadata,created_at,id FROM $e WHERE order_id IN ($in) ORDER BY order_id ASC,created_at ASC,id ASC");foreach($events as $r){$id=(int)$r->order_id;$orders[$id]??=array('value'=>0,'currency'=>'','purchase_at'=>'','shipped_at'=>'','delivered_at'=>'','returned_at'=>'','cancelled_at'=>'','first'=>array(),'last'=>array(),'purchased'=>false);$m=$r->metadata?json_decode($r->metadata,true):array();if(isset($m['order_total']))$orders[$id]['value']=(float)$m['order_total'];if(!empty($m['currency']))$orders[$id]['currency']=sanitize_text_field($m['currency']);if($r->event_type==='purchase'){$orders[$id]['purchased']=true;$orders[$id]['purchase_at']=$r->created_at;$orders[$id]['first']=self::touch($m,'first');$orders[$id]['last']=self::touch($m,'last');if(!$orders[$id]['last'])$orders[$id]['last']=self::touch($m,'');}$st=(string)$r->new_status;if(in_array($st,array('smf-shipped','smf-delivered','completed'),true)&&empty($orders[$id]['shipped_at']))$orders[$id]['shipped_at']=$r->created_at;if(in_array($st,array('smf-delivered','completed'),true)&&empty($orders[$id]['delivered_at']))$orders[$id]['delivered_at']=$r->created_at;if($st==='smf-returned'&&empty($orders[$id]['returned_at']))$orders[$id]['returned_at']=$r->created_at;if($st==='cancelled'&&empty($orders[$id]['cancelled_at']))$orders[$id]['cancelled_at']=$r->created_at;}}
  $sp=$wpdb->get_results($wpdb->prepare("SELECT campaign_id,amount,currency FROM $s WHERE spend_date BETWEEN %s AND %s AND currency=%s",$since,$until,$currency));$spend=0;$campaign_spend=array();foreach($sp as $r){$a=(float)$r->amount;$spend+=$a;if($r->campaign_id!=='')$campaign_spend[$r->campaign_id]=($campaign_spend[$r->campaign_id]??0)+$a;}
  $cogs=self::pct(get_option('smf_cogs_percent',0));$fee=self::pct(get_option('smf_payment_fee_percent',0));$delivery=self::money(get_option('smf_courier_delivery_cost',0));$return=self::money(get_option('smf_courier_return_cost',0));$rows=array();$summary=array('spend'=>$spend,'purchase_revenue'=>0,'delivered_revenue'=>0,'delivered_orders'=>0,'returned_orders'=>0,'returned_revenue'=>0,'cancelled_orders'=>0,'cancelled_revenue'=>0,'cogs'=>0,'payment_fees'=>0,'delivery_cost'=>0,'return_cost'=>0,'contribution_profit'=>-$spend,'contribution_margin'=>0,'roas'=>0);
  foreach($orders as $o){if(!$o['purchased']||strtoupper($o['currency'])!==strtoupper($currency))continue;$v=$o['value'];$summary['purchase_revenue']+=$v;$f=self::campaign($o['first']);$l=self::campaign($o['last']);$credits=array();if($model==='first_touch')$credits=array($f=>1);elseif($model==='first_last'&&$f!==$l)$credits=array($f=>.5,$l=>.5);elseif($model==='assisted'&&$f!==$l&&$f!=='Direct / Unattributed')$credits=array($f=>1);else $credits=array($l=>1);foreach($credits as $camp=>$w){if(!isset($rows[$camp]))$rows[$camp]=array('campaign'=>$camp,'spend'=>0,'delivered_revenue'=>0,'delivered_orders'=>0,'returned_revenue'=>0,'returned_orders'=>0,'cancelled_revenue'=>0,'orders'=>0);$rows[$camp]['orders']++;if(!empty($o['delivered_at'])){$rows[$camp]['delivered_revenue']+=$v*$w;$rows[$camp]['delivered_orders']++;}if(!empty($o['returned_at'])){$rows[$camp]['returned_revenue']+=$v*$w;$rows[$camp]['returned_orders']++;}if(!empty($o['cancelled_at']))$rows[$camp]['cancelled_revenue']+=$v*$w;}
   if(!empty($o['delivered_at'])){$summary['delivered_orders']++;$summary['delivered_revenue']+=$v;$summary['cogs']+=$v*$cogs/100;$summary['payment_fees']+=$v*$fee;$summary['delivery_cost']+=$delivery;}
   if(!empty($o['returned_at'])){$summary['returned_orders']++;$summary['returned_revenue']+=$v;$summary['return_cost']+=$return;}
   if(!empty($o['cancelled_at'])){$summary['cancelled_orders']++;$summary['cancelled_revenue']+=$v;}
  }
  $summary['contribution_profit']=$summary['delivered_revenue']-$summary['cogs']-$summary['payment_fees']-$summary['delivery_cost']-$summary['return_cost']-$spend;$summary['contribution_margin']=$summary['delivered_revenue']>0?($summary['contribution_profit']/$summary['delivered_revenue']*100):0;$summary['roas']=$spend>0?$summary['delivered_revenue']/$spend:0;
  foreach($rows as &$r){$r['spend']=$campaign_spend[$r['campaign']]??0;$r['cogs']=$r['delivered_revenue']*$cogs/100;$r['payment_fees']=$r['delivered_revenue']*$fee;$r['delivery_cost']=$r['delivered_orders']*$delivery;$r['return_cost']=$r['returned_orders']*$return;$r['profit']=$r['delivered_revenue']-$r['cogs']-$r['payment_fees']-$r['delivery_cost']-$r['return_cost']-$r['spend'];$r['margin']=$r['delivered_revenue']>0?$r['profit']/$r['delivered_revenue']*100:0;$r['roas']=$r['spend']>0?$r['delivered_revenue']/$r['spend']:0;$r['decision']=$r['profit']>0?($r['margin']>=20?'SCALE':'WATCH'):($r['spend']>0?'KILL':'NO SPEND');}unset($r);usort($rows,function($a,$b){return $b['profit']<=>$a['profit'];});return array('period'=>array('days'=>$days,'since'=>$since,'until'=>$until),'currency'=>$currency,'model'=>$model,'summary'=>$summary,'campaigns'=>array_values($rows),'assumptions'=>array('cogs_percent'=>$cogs,'payment_fee_percent'=>$fee,'courier_delivery_cost'=>$delivery,'courier_return_cost'=>$return));
 }
 public static function render(){if(!current_user_can('manage_woocommerce'))return;$days=isset($_GET['period'])?absint($_GET['period']):30;$days=in_array($days,array(7,30,90),true)?$days:30;$model=SMF_Attribution_Model::normalize_model(isset($_GET['model'])?wp_unslash($_GET['model']):get_option('smf_attribution_model','last_touch'));$x=self::report($days,'BDT',$model);$z=$x['summary'];?><div class="wrap smf-wrap"><h1>Profitability Intelligence</h1><p>Contribution economics layered on top of delivered-order attribution. Configure assumptions below; this is not statutory accounting.</p><form method="get" class="smf-period-bar"><input type="hidden" name="page" value="smf-profitability"><label>Model <select name="model"><?php foreach(array('last_touch'=>'Last Touch','first_touch'=>'First Touch','first_last'=>'First + Last (50/50)','assisted'=>'Assisted') as $k=>$v):?><option value="<?php echo esc_attr($k);?>" <?php selected($model,$k);?>><?php echo esc_html($v);?></option><?php endforeach;?></select></label><?php foreach(array(7,30,90) as $p):?><a class="button <?php echo $days===$p?'button-primary':'';?>" href="<?php echo esc_url(admin_url('admin.php?page=smf-profitability&period='.$p.'&model='.rawurlencode($model)));?>"><?php echo $p;?> days</a><?php endforeach;?><button class="button">Apply</button></form><form method="post" action="<?php echo esc_url(admin_url('options.php'));?>" style="max-width:760px"><table class="form-table"><tr><th>COGS %</th><td><input name="smf_cogs_percent" type="number" min="0" max="100" step="0.01" value="<?php echo esc_attr($x['assumptions']['cogs_percent']);?>"> %</td></tr><tr><th>Payment fee %</th><td><input name="smf_payment_fee_percent" type="number" min="0" max="100" step="0.01" value="<?php echo esc_attr($x['assumptions']['payment_fee_percent']);?>"> %</td></tr><tr><th>Courier delivery cost</th><td><input name="smf_courier_delivery_cost" type="number" min="0" step="0.01" value="<?php echo esc_attr($x['assumptions']['courier_delivery_cost']);?>"> / delivered order</td></tr><tr><th>Courier return cost</th><td><input name="smf_courier_return_cost" type="number" min="0" step="0.01" value="<?php echo esc_attr($x['assumptions']['courier_return_cost']);?>"> / returned order</td></tr></table><?php settings_fields('smf_settings');?><button class="button button-primary">Save economics assumptions</button></form><div class="smf-cards"><div class="smf-card"><span>Ad Spend</span><strong><?php echo number_format_i18n($z['spend'],2);?></strong></div><div class="smf-card"><span>Delivered Revenue</span><strong><?php echo number_format_i18n($z['delivered_revenue'],2);?></strong></div><div class="smf-card"><span>Contribution Profit</span><strong><?php echo number_format_i18n($z['contribution_profit'],2);?></strong><small>Revenue − operating assumptions − ad spend</small></div><div class="smf-card"><span>Contribution Margin</span><strong><?php echo number_format_i18n($z['contribution_margin'],1);?>%</strong></div></div><div class="smf-panel"><h2>Campaign profitability</h2><div class="smf-table-wrap"><table class="smf-table"><thead><tr><th>Campaign / ID</th><th>Spend</th><th>Delivered</th><th>Returned</th><th>Profit</th><th>Margin</th><th>ROAS</th><th>Decision</th></tr></thead><tbody><?php foreach($x['campaigns'] as $r):?><tr><td><strong><?php echo esc_html($r['campaign']);?></strong></td><td><?php echo number_format_i18n($r['spend'],2);?></td><td><?php echo number_format_i18n($r['delivered_revenue'],2);?></td><td><?php echo number_format_i18n($r['returned_revenue'],2);?></td><td><?php echo number_format_i18n($r['profit'],2);?></td><td><?php echo number_format_i18n($r['margin'],1);?>%</td><td><?php echo number_format_i18n($r['roas'],2);?>×</td><td><?php echo esc_html($r['decision']);?></td></tr><?php endforeach;?></tbody></table></div></div><div class="smf-panel"><h2>Economics</h2><p class="smf-muted">COGS and payment fees are percentage assumptions. Courier costs are per-order assumptions. Returned revenue is shown for risk visibility but is not counted as realized revenue. Campaign spend is matched by campaign_id; name-only attribution has no spend unless the spend table uses the same identifier. Decisions are operating heuristics.</p></div></div><?php }
}
